### 3. Handling "Unknown" Errors Gracefully

What if an error occurs that we didn’t anticipate? For example, a `TypeError` thrown by a third-party library?

In our current setup, `getUserName` only returns `GetUserNameError`. But what if the function itself throws an exception?

#### Solution: Wrap the Domain Function

We can create a higher-order function that catches any unexpected exceptions and converts them into a generic `UnknownError`.

```typescript
// errors.ts (Add this)
export interface UnknownError {
  readonly _tag: "Unknown";
  readonly originalError: unknown;
}

export const unknownError = (originalError: unknown): UnknownError => ({
  _tag: "Unknown",
  originalError,
});

// Update the union type
export type GetUserNameError = UserNotFoundError | DbConnectionError | UnknownError;
```

#### Update the API Function

```typescript
// api.ts
import { Either, left, right } from "fp-ts/lib/Either";
import { GetUserNameResult } from "./types";
import { userNotFound, dbConnectionError, unknownError } from "./errors";

export const getUserName = (userId: string): GetUserNameResult => {
  try {
    // Simulate a database lookup
    if (userId === "non-existent") {
      return left(userNotFound(userId));
    }

    if (Math.random() < 0.1) {
      return left(dbConnectionError("Connection timeout"));
    }

    return right(`User_${userId}`);
  } catch (e) {
    // Catch any unexpected errors and wrap them
    return left(unknownError(e));
  }
};
```

#### Update the UI State Mapper

```typescript
// uiState.ts (Update the switch statement)
case "Unknown":
  return {
    status: "error",
    message: "An unexpected error occurred. Please contact support.",
    retryable: false,
  };
```

Now, even if something goes wrong that we didn’t anticipate, the UI will still render a graceful error message instead of crashing.

