### 6. Handling Timeouts and Cancellation

`TaskEither` doesn’t have built-in timeout or cancellation, but we can add them using higher-order functions.

#### Timeout

```typescript
import { TaskEither } from "fp-ts/lib/TaskEither";
import { pipe } from "fp-ts/lib/function";

export const withTimeout = <E, A>(
  taskEither: TaskEither<E, A>,
  timeoutMs: number,
  timeoutError: E
): TaskEither<E, A> => {
  return () =>
    new Promise((resolve) => {
      let isResolved = false;

      const timeoutId = setTimeout(() => {
        if (!isResolved) {
          isResolved = true;
          resolve(left(timeoutError));
        }
      }, timeoutMs);

      taskEither()
        .then((result) => {
          if (!isResolved) {
            isResolved = true;
            clearTimeout(timeoutId);
            resolve(result);
          }
        })
        .catch((error) => {
          if (!isResolved) {
            isResolved = true;
            clearTimeout(timeoutId);
            resolve(left(error));
          }
        });
    });
};

// Usage
const getUserWithTimeout = (userId: string) =>
  pipe(
    getUserNameAsync(userId),
    withTimeout(5000, dbConnectionError("Request timed out"))
  );
```

#### Cancellation

Cancellation is more complex and typically requires a `AbortController` or a similar mechanism. `fp-ts` doesn’t have a built-in cancellation mechanism for `TaskEither`, but you can integrate it with `AbortController` if needed.

```typescript
export const withCancellation = <E, A>(
  taskEither: TaskEither<E, A>,
  signal: AbortSignal
): TaskEither<E, A> => {
  return () =>
    new Promise((resolve) => {
      if (signal.aborted) {
        resolve(left(new Error("Aborted")));
        return;
      }

      const onAbort = () => {
        resolve(left(new Error("Aborted")));
      };

      signal.addEventListener("abort", onAbort, { once: true });

      taskEither()
        .then((result) => {
          signal.removeEventListener("abort", onAbort);
          resolve(result);
        })
        .catch((error) => {
          signal.removeEventListener("abort", onAbort);
          resolve(left(error));
        });
    });
};
```

