### 4. Sending Errors to a Monitoring Service (e.g., Sentry)

To integrate with a service like Sentry, we just need to implement the `Logger` interface.

```typescript
// sentryLogger.ts
import * as Sentry from "@sentry/react";
import { Logger } from "./logger";
import { redactSensitiveData } from "./redact";

export const sentryLogger: Logger = {
  info: (message, context) => {
    // Sentry doesn't have a direct "info" level, so we use "log" or "debug"
    Sentry.captureMessage(message, "info");
    if (context) {
      Sentry.setContext("context", redactSensitiveData(context));
    }
  },
  error: (message, context) => {
    // Capture the error with context
    Sentry.captureException(new Error(message), {
      extra: redactSensitiveData(context || {}),
    });
  },
};
```

Now, in production, you can swap the logger:

```typescript
// config.ts
import { consoleLogger } from "./logger";
import { sentryLogger } from "./sentryLogger";

export const logger = process.env.NODE_ENV === "production" ? sentryLogger : consoleLogger;
```

And update `api.ts` to use `logger` instead of `consoleLogger`.

