### 5. Handling Sensitive Data in Error Logs

We already have `redactSensitiveData`, but let's make it more robust. Sometimes, sensitive data is nested.

```typescript
// redact.ts (Enhanced)
export const redactSensitiveData = (obj: Record<string, unknown>): Record<string, unknown> => {
  const sensitiveKeys = ["password", "token", "ssn", "creditCard", "apiKey"];

  const redact = (value: unknown): unknown => {
    if (typeof value === "object" && value !== null) {
      const obj = value as Record<string, unknown>;
      const redactedObj: Record<string, unknown> = {};
      for (const key of Object.keys(obj)) {
        if (sensitiveKeys.includes(key.toLowerCase())) {
          redactedObj[key] = "***REDACTED***";
        } else {
          redactedObj[key] = redact(obj[key]);
        }
      }
      return redactedObj;
    }
    return value;
  };

  return redact(obj) as Record<string, unknown>;
};
```

This recursively redacts sensitive keys at any depth.

