### 3. Integrating Retry and Recovery into the API Layer

Now, we update our `api.ts` to use these utilities. We can combine **retry** for transient errors and **recovery** for permanent errors.

```typescript
// api.ts
import { TaskEither, left, right } from "fp-ts/lib/TaskEither";
import { pipe } from "fp-ts/lib/function";
import { GetUserNameError } from "./errors";
import { userNotFound, dbConnectionError, unknownError } from "./errors";
import { withLogging } from "./loggingMiddleware";
import { withRetry } from "./retry";
import { withRecovery } from "./recovery";
import { consoleLogger } from "./logger";

// The core pure logic (no logging, no retry here!)
const getUserNameCore = (userId: string): TaskEither<GetUserNameError, string> => {
  return () =>
    new Promise((resolve) => {
      setTimeout(() => {
        if (userId === "non-existent") {
          resolve(left(userNotFound(userId)));
        } else if (Math.random() < 0.1) {
          // Simulate a transient DB error
          resolve(left(dbConnectionError("Connection timeout", true)));
        } else if (Math.random() < 0.05) {
          // Simulate a permanent DB error
          resolve(left(dbConnectionError("Database corrupted", false)));
        } else {
          resolve(right(`User_${userId}`));
        }
      }, 500);
    });
};

/**
 * Public API function with logging, retry, and recovery.
 */
export const getUserNameAsync = (userId: string): TaskEither<GetUserNameError, string> => {
  return pipe(
    getUserNameCore(userId),
    // 1. Retry transient errors up to 3 times with 100ms base delay
    withRetry(3, 100, (e) => e.isTransient),
    // 2. If it still fails, log the error
    withLogging(consoleLogger, "getUserName", { userId }),
    // 3. If it's a permanent error, recover with a default value
    withRecovery((e) => {
      if (e._tag === "UserNotFound") {
        // For UserNotFound, we might want to return a default user
        return TaskEither.right("Anonymous");
      }
      // For other errors, re-throw
      return TaskEither.left(e);
    })
  );
};
```

#### Key Benefits:
1. **Composability:** We can chain `withRetry`, `withLogging`, and `withRecovery` in any order.
2. **Transience Handling:** Only transient errors are retried. Permanent errors fail immediately.
3. **Exponential Backoff:** Prevents overwhelming a failing service.
4. **Graceful Degradation:** If all retries fail, we can recover with a default value or an alternative data source.

