      callCount++;
      return Promise.resolve(left(dbConnectionError("Corrupted", false)));
    };

    const retriedTask = withRetry(task(), 3, 10, (e) => e.isTransient);
    const result = await retriedTask();

    expect(result._tag).toBe("Left");
    expect(callCount).toBe(1); // Only called once
  });
});
