### 4. Step 2: Collecting All Errors (Non-Fail-Fast)

Sometimes, you want to **collect all errors** from a batch, not just the first one. This is useful for:
-   Reporting all validation errors at once.
-   Processing as many items as possible, even if some fail.

`fp-ts` doesn’t have a built-in `traverseAllErrors` for `TaskEither`, but we can create one using `TaskEither.traverse` with a custom error type that accumulates errors.

#### Approach: Use a Custom Error Type

We can define a new error type that holds a list of errors:

```typescript
// errors.ts
export type BatchError<E> = {
  _tag: "BatchError";
  errors: E[];
};

export const batchError = <E>(errors: E[]): BatchError<E> => ({
  _tag: "BatchError",
  errors,
});
```

Now, we can create a `traverseAllErrors` function:

```typescript
// batch.ts
import { TaskEither, left, right } from "fp-ts/lib/TaskEither";
import { pipe } from "fp-ts/lib/function";
import { BatchError, batchError } from "./errors";

/**
 * Traverses a list of values, applying a function that returns a TaskEither.
 * Collects all errors and returns them in a BatchError if any fail.
 * If all succeed, returns the list of results.
 */
export const traverseAllErrors = <E, A, B>(
  fa: readonly A[],
  f: (a: A) => TaskEither<E, B>
): TaskEither<BatchError<E>, B[]> => {
  return () => {
    const promises = fa.map((a) => f(a)());
    return Promise.all(promises).then((results) => {
      const errors: E[] = [];
      const successes: B[] = [];

      for (const result of results) {
        if (result._tag === "Right") {
          successes.push(result.right);
        } else {
          errors.push(result.left);
        }
      }

      if (errors.length > 0) {
        return left(batchError(errors));
      }

      return right(successes);
    });
  };
};
```

#### Usage:

```typescript
// api.ts
import { traverseAllErrors } from "./batch";
import { BatchError } from "./errors";

export const getUserNamesWithAllErrors = (
  userIds: string[]
): TaskEither<BatchError<GetUserNameError>, string[]> => {
  return traverseAllErrors(userIds, (id) => getUserNameCore(id));
};
```

**Usage:**
```typescript
const result = await getUserNamesWithAllErrors(["1", "non-existent", "3"])();
if (result._tag === "Right") {
  console.log(result.right); // ["User_1", "User_3"]
} else {
  console.log(result.left); // { _tag: "BatchError", errors: [UserNotFound("non-existent")] }
}
```

