### 5. Combining Retry, Logging, and Batching

Now, let’s combine all our previous work:
1.  **Retry** transient errors for each individual operation.
2.  **Log** each operation.
3.  **Batch** the operations and collect all errors.

```typescript
// api.ts
import { TaskEither, left, right } from "fp-ts/lib/TaskEither";
import { pipe } from "fp-ts/lib/function";
import { GetUserNameError, BatchError } from "./errors";
import { getUserNameCore } from "./core";
import { withRetry } from "./retry";
import { withLogging } from "./loggingMiddleware";
import { consoleLogger } from "./logger";
import { traverseAllErrors } from "./batch";

/**
 * Fetches user names for multiple users.
 * - Retries transient errors for each user.
 * - Logs each operation.
 * - Collects all errors from the batch.
 */
export const getUserNamesRobust = (
  userIds: string[]
): TaskEither<BatchError<GetUserNameError>, string[]> => {
  return traverseAllErrors(userIds, (id) => {
    return pipe(
      getUserNameCore(id),
      // 1. Retry transient errors
      withRetry(3, 100, (e) => e.isTransient),
      // 2. Log the operation
      withLogging(consoleLogger, "getUserName", { userId: id })
    );
  });
};
```

