  });

  it("should return all results if no errors", async () => {
    const tasks = [
      TaskEither.right("A"),
      TaskEither.right("B"),
      TaskEither.right("C"),
    ];

    const result = await traverseAllErrors(tasks, (t) => t)();

    expect(result._tag).toBe("Right");
    if (result._tag === "Right") {
      expect(result.right).toEqual(["A", "B", "C"]);
    }
  });
});
