### 4. Handling the Enriched Error

Now, when an error occurs, it will be wrapped in a `ContextualError`. We can extract the original error and the context for logging or API responses.

```typescript
// handler.ts
import { ContextualError } from "./errors";

export const handleApiError = (error: ContextualError<unknown>): void => {
  console.error("API Error:", {
    operation: error.context.operation,
    requestId: error.context.requestId,
    timestamp: error.context.timestamp,
    originalError: error.originalError,
  });

  // In a real API, you might return a sanitized response:
  // return {
  //   status: 500,
  //   body: {
  //     error: error.originalError._tag,
  //     requestId: error.context.requestId,
  //   }
  // };
};
```

