### 5. Preserving Stack Traces

One of the challenges with functional error handling is that **stack traces can be lost** when errors are wrapped in objects. To preserve stack traces:

1.  **Use `Error` objects for the original error:** Instead of plain objects, use `Error` instances for the `originalError`.
2.  **Capture the stack trace at the point of failure:** Use `new Error().stack` or a library like `stacktrace-js`.

#### Improved Error Type

```typescript
// errors.ts
export type ContextualError<E extends Error> = {
  _tag: "ContextualError";
  originalError: E;
  context: {
    operation: string;
    requestId?: string;
    timestamp: string;
    [key: string]: unknown;
  };
};

export const contextualError = <E extends Error>(
  originalError: E,
  context: ContextualError<E>["context"]
): ContextualError<E> => ({
  _tag: "ContextualError",
  originalError,
  context,
});
```

#### Updating `getUserNameCore` to Use `Error`

```typescript
// core.ts
import { TaskEither } from "fp-ts/lib/TaskEither";
import { pipe } from "fp-ts/lib/function";
import { withContext } from "./context";

export class UserNotFoundError extends Error {
  constructor(public userId: string) {
    super(`User not found: ${userId}`);
    this.name = "UserNotFoundError";
  }
}

export const getUserNameCore = (userId: string): TaskEither<UserNotFoundError, string> => {
  const fetchUserName = (): Promise<string> => {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (userId === "non-existent") {
          reject(new UserNotFoundError(userId)); // Use Error instance
        } else {
          resolve(`User_${userId}`);
        }
      }, 100);
    });
  };

  return pipe(
    TaskEither.fromPromise<UserNotFoundError, string>(fetchUserName),
    withContext({ operation: "getUserName", userId })
  );
};
```

Now, `error.originalError.stack` will contain the stack trace from where the error was thrown.

