### 6. Testing Contextual Errors

```typescript
// context.test.ts
import { TaskEither, right, left } from "fp-ts/lib/TaskEither";
import { withContext } from "./context";
import { contextualError } from "./errors";

describe("withContext", () => {
  it("should add context to the error", async () => {
    const error = new Error("Something went wrong");
    const te = TaskEither.left(error);

    const result = await withContext(te, { operation: "testOperation" })();

    expect(result._tag).toBe("Left");
    if (result._tag === "Left") {
      expect(result.left._tag).toBe("ContextualError");
      expect(result.left.originalError).toBe(error);
      expect(result.left.context.operation).toBe("testOperation");
      expect(result.left.context.timestamp).toBeDefined();
    }
  });

  it("should not modify the success value", async () => {
    const te = TaskEither.right("success");

    const result = await withContext(te, { operation: "testOperation" })();

    expect(result._tag).toBe("Right");
    if (result._tag === "Right") {
      expect(result.right).toBe("success");
    }
  });
});
```

