### 6. Step 4: Handling the Result in the API

Now, let’s see how the API handler would use this.

```typescript
// handler.ts
import { pipe } from "fp-ts/lib/function";
import { getUserNamesPartialSuccess } from "./api";
import { PartialSuccess } from "./types";

export const handleGetUserNames = async (
  userIds: string[],
  requestId: string
): Promise<{ status: number, body: any }> => {
  const result = await getUserNamesPartialSuccess(userIds, requestId)();

  if (result._tag === "Left") {
    // This should rarely happen, as traversePartial doesn't fail
    // But if it does, return a 500 error
    return {
      status: 500,
      body: { error: "Internal Server Error" }
    };
  }

  const { successes, failures } = result.right;

  // If there are no failures, return 200 with all successes
  if (failures.length === 0) {
    return {
      status: 200,
      body: { users: successes }
    };
  }

  // If there are failures, return 207 (Multi-Status) or 200 with partial data
  // 207 is a standard HTTP status for partial success
  return {
    status: 207,
    body: {
      users: successes,
      errors: failures.map((f) => ({
        userId: userIds[f.index],
        error: f.error.message
      }))
    }
  };
};
```

