### 4. Step 2: Integrating with Our User Service

Now, let’s wrap our `getUserNameWithFallbackService` with a circuit breaker.

```typescript
// api.ts
import { TaskEither } from "fp-ts/lib/TaskEither";
import { pipe } from "fp-ts/lib/function";
import { ContextualError, UserNotFoundError, TransientError } from "./errors";
import { getUserNameWithFallbackService } from "./services";
import { withRetry } from "./retry";
import { withLogging } from "./loggingMiddleware";
import { consoleLogger } from "./logger";
import { traversePartial } from "./partialSuccess";
import { PartialSuccess } from "./types";
import { withContext } from "./context";
import { withCircuitBreaker } from "./circuitBreaker";

// Configuration for the circuit breaker
const circuitBreakerConfig = {
  failureThreshold: 5, // Trip after 5 failures
  resetTimeout: 30000  // Wait 30 seconds before testing recovery
};

/**
 * Fetches user names with circuit breaker protection.
 */
export const getUserNamesWithCircuitBreaker = (
  userIds: string[],
  requestId: string
): TaskEither<ContextualError<UserNotFoundError | TransientError>, PartialSuccess<string, UserNotFoundError | TransientError>> => {
  const userTasks: TaskEither<UserNotFoundError | TransientError, string>[] = userIds.map((id) => {
    return pipe(
      getUserNameWithFallbackService(id),
      // 1. Protect with circuit breaker
      withCircuitBreaker(circuitBreakerConfig),
      // 2. Retry transient errors (if circuit is closed/half-open)
      withRetry(2, 100, (e) => e instanceof TransientError),
      // 3. Log the operation
      withLogging(consoleLogger, "getUserName", { userId: id, requestId })
    );
  });

  return pipe(
    traversePartial(userTasks),
    TaskEither.fromTask,
    withContext({ operation: "getUserNames", requestId })
  );
};
```

> **Important**: The order of middleware matters.
> -   `withCircuitBreaker` should be **outermost** (or close to it) so that if the circuit is open, we don’t even attempt retries.
> -   `withRetry` should be **inside** the circuit breaker so that retries are counted as failures if they fail.

